// Generate .env.production.local from the private public-env mirror.
//
// Every value here is public by design (the same values are already inlined
// into the shipped Android bundle), but they still must not be committed, so
// the generated file is gitignored and this script runs at build time.
//
// Source order: an explicit PUBLIC_ENV_FILE, then the standard local mirror.
// If neither exists the build still proceeds with empty values; the app shows
// a clear "not configured" screen rather than failing mysteriously at runtime.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const target = resolve(here, '../.env.production.local');

// VITE_ name on the left, the EXPO_PUBLIC_ name it mirrors on the right, so the
// web app and the phone read the same values from one source.
const MAPPING = {
  VITE_SUPABASE_URL: 'EXPO_PUBLIC_SUPABASE_URL',
  VITE_SUPABASE_ANON_KEY: 'EXPO_PUBLIC_SUPABASE_ANON_KEY',
  VITE_API_BASE_URL: 'EXPO_PUBLIC_SIDEKICK_API_BASE_URL',
  VITE_SENTRY_DSN: 'EXPO_PUBLIC_SENTRY_DSN',
  VITE_GOOGLE_WEB_CLIENT_ID: 'EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID',
};

const SECRET_NAME = /(SERVICE_ROLE|SECRET|PRIVATE_KEY|_TOKEN|PASSWORD|WEBHOOK)/i;

export function parseEnvFile(text) {
  const values = {};
  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq <= 0) continue;
    const key = trimmed.slice(0, eq).trim();
    let value = trimmed.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    values[key] = value;
  }
  return values;
}

export function renderPublicEnv(source) {
  const lines = [
    '# Generated by scripts/write-public-env.mjs. Do not commit.',
    '# Public values only: these are already inlined into the shipped Android app.',
  ];
  for (const [viteName, expoName] of Object.entries(MAPPING)) {
    if (SECRET_NAME.test(expoName)) {
      throw new Error(`refusing to inline ${expoName}: the name looks like a server secret`);
    }
    lines.push(`${viteName}=${source[expoName] ?? ''}`);
  }
  return `${lines.join('\n')}\n`;
}

function resolveSourceFile() {
  const explicit = process.env.PUBLIC_ENV_FILE;
  if (explicit && existsSync(explicit)) return explicit;
  const mirror = resolve(homedir(), '.coworker-ai/live-provider.env');
  if (existsSync(mirror)) return mirror;
  return null;
}

function main() {
  const sourceFile = resolveSourceFile();
  const source = sourceFile ? parseEnvFile(readFileSync(sourceFile, 'utf8')) : {};
  writeFileSync(target, renderPublicEnv(source), 'utf8');
  const filled = Object.keys(MAPPING).filter((name) => (source[MAPPING[name]] ?? '') !== '');
  process.stdout.write(
    sourceFile
      ? `public env written from ${sourceFile} (${filled.length}/${Object.keys(MAPPING).length} values present)\n`
      : 'public env written EMPTY (no PUBLIC_ENV_FILE and no local mirror found)\n',
  );
}

if (process.argv[1] && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url))) {
  main();
}
